```suggestion
    // Evaluate individual success criteria based on their text
    const evaluateCriteria = (criteria: string): boolean => {
      const normalized = criteria.toLowerCase().trim()
      const hasResults = results.length > 0

      // Criteria focused on tests, e.g. "All tests pass"
      if (normalized.includes("all tests") || (normalized.includes("all") && normalized.includes("tests"))) {
        const allTasks = plan.phases.flatMap((p) => p.tasks)
        const testTaskIds = new Set(
          allTasks
            .filter(
              (t) =>
                t.type === "testing" ||
                t.title.toLowerCase().includes("test") ||
                t.description.toLowerCase().includes("test"),
            )
            .map((t) => t.id),
        )

        // If we have an "all tests" criterion but no identifiable test tasks,
        // treat the criterion as unmet rather than assuming it passed.
