          return false
        }

        const relevantResults = results.filter((r) => testTaskIds.has(r.taskId))

        // If there are test tasks but no corresponding results, we cannot say tests passed.
        if (relevantResults.length === 0) {
          return false
        }

        return relevantResults.every((r) => r.status === "success")
